-- Migracion de MySQL/Laragon a PostgreSQL 17 (compatible con Neon)
-- Datos INSERT conservados; no se regeneran ni modifican los registros.
BEGIN;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = off;

CREATE TYPE "enum_orders_status" AS ENUM ('pending','paid','shipped','cancelled');
CREATE TYPE "enum_payments_payment_method" AS ENUM ('paypal','stripe','bank_transfer');
CREATE TYPE "enum_payments_status" AS ENUM ('pending','completed','failed');
CREATE TYPE "enum_products_status" AS ENUM ('active','inactive');
CREATE TYPE "enum_users_role" AS ENUM ('admin','customer');

CREATE TABLE IF NOT EXISTS "brands" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(255) NOT NULL,
  "slug" varchar(255) NOT NULL,
  "description" text,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "brands_slug_unique" UNIQUE ("slug")
);
CREATE TABLE IF NOT EXISTS "cart" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "quantity" int NOT NULL DEFAULT 1,
  "price" decimal(10,2) NOT NULL,
  "sub_total" decimal(10,2) NOT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "categories" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(255) NOT NULL,
  "slug" varchar(255) NOT NULL,
  "description" text,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "categories_slug_unique" UNIQUE ("slug")
);
CREATE TABLE IF NOT EXISTS "failed_jobs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "uuid" varchar(255) NOT NULL,
  "connection" text NOT NULL,
  "queue" text NOT NULL,
  "payload" text NOT NULL,
  "exception" text NOT NULL,
  "failed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "failed_jobs_uuid_unique" UNIQUE ("uuid")
);
CREATE TABLE IF NOT EXISTS "migrations" (
  "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "migration" varchar(255) NOT NULL,
  "batch" int NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "orders" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "user_address_id" bigint DEFAULT NULL,
  "total_price" decimal(10,2) NOT NULL,
  "status" enum_orders_status NOT NULL DEFAULT 'pending',
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "order_items" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "order_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "quantity" int NOT NULL,
  "price" decimal(10,2) NOT NULL,
  "subtotal" decimal(10,2) NOT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" (
  "email" varchar(255) NOT NULL,
  "token" varchar(255) NOT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("email")
);
CREATE TABLE IF NOT EXISTS "payments" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "order_id" bigint NOT NULL,
  "payment_method" enum_payments_payment_method NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "transaction_id" varchar(255) DEFAULT NULL,
  "transaction_json" json DEFAULT NULL,
  "status" enum_payments_status NOT NULL DEFAULT 'pending',
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tokenable_type" varchar(255) NOT NULL,
  "tokenable_id" bigint NOT NULL,
  "name" varchar(255) NOT NULL,
  "token" varchar(64) NOT NULL,
  "abilities" text,
  "last_used_at" timestamp NULL DEFAULT NULL,
  "expires_at" timestamp NULL DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "personal_access_tokens_token_unique" UNIQUE ("token")
);
CREATE TABLE IF NOT EXISTS "products" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "category_id" bigint NOT NULL,
  "brand_id" bigint NOT NULL,
  "name" varchar(255) NOT NULL,
  "slug" varchar(255) NOT NULL,
  "description" text,
  "price" decimal(10,2) NOT NULL,
  "price2" decimal(10,2) DEFAULT NULL,
  "stock" int NOT NULL DEFAULT 0,
  "image" varchar(255) DEFAULT NULL,
  "status" enum_products_status NOT NULL DEFAULT 'active',
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "products_slug_unique" UNIQUE ("slug")
);
CREATE TABLE IF NOT EXISTS "reviews" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "rating" integer NOT NULL,
  "comment" text,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "shipping_addresses" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "address" text NOT NULL,
  "city" varchar(100) NOT NULL,
  "state" varchar(100) NOT NULL,
  "zip_code" varchar(20) NOT NULL,
  "country" varchar(100) NOT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(255) NOT NULL,
  "email" varchar(255) NOT NULL,
  "email_verified_at" timestamp NULL DEFAULT NULL,
  "password" varchar(255) NOT NULL,
  "phone" varchar(20) DEFAULT NULL,
  "role" enum_users_role NOT NULL DEFAULT 'customer',
  "address" text,
  "remember_token" varchar(100) DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_email_unique" UNIQUE ("email")
);
CREATE TABLE IF NOT EXISTS "wishlists" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "created_at" timestamp NULL DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id")
);

DELETE FROM "brands";
DELETE FROM "cart";
DELETE FROM "categories";
DELETE FROM "failed_jobs";
DELETE FROM "migrations";
DELETE FROM "orders";
DELETE FROM "order_items";
DELETE FROM "password_reset_tokens";
DELETE FROM "payments";
DELETE FROM "personal_access_tokens";
DELETE FROM "products";
DELETE FROM "reviews";
DELETE FROM "shipping_addresses";
DELETE FROM "users";
DELETE FROM "wishlists";

CREATE INDEX "cart_user_id_foreign" ON "cart" ("user_id");
CREATE INDEX "cart_product_id_foreign" ON "cart" ("product_id");
CREATE INDEX "orders_user_id_foreign" ON "orders" ("user_id");
CREATE INDEX "orders_user_address_id_foreign" ON "orders" ("user_address_id");
CREATE INDEX "order_items_order_id_foreign" ON "order_items" ("order_id");
CREATE INDEX "order_items_product_id_foreign" ON "order_items" ("product_id");
CREATE INDEX "payments_order_id_foreign" ON "payments" ("order_id");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" ON "personal_access_tokens" ("tokenable_type","tokenable_id");
CREATE INDEX "products_category_id_foreign" ON "products" ("category_id");
CREATE INDEX "products_brand_id_foreign" ON "products" ("brand_id");
CREATE INDEX "reviews_user_id_foreign" ON "reviews" ("user_id");
CREATE INDEX "reviews_product_id_foreign" ON "reviews" ("product_id");
CREATE INDEX "shipping_addresses_user_id_foreign" ON "shipping_addresses" ("user_id");
CREATE INDEX "wishlists_user_id_foreign" ON "wishlists" ("user_id");
CREATE INDEX "wishlists_product_id_foreign" ON "wishlists" ("product_id");

ALTER TABLE "cart" ADD CONSTRAINT "cart_product_id_foreign" FOREIGN KEY (product_id) REFERENCES "products" (id) ON DELETE CASCADE;
ALTER TABLE "cart" ADD CONSTRAINT "cart_user_id_foreign" FOREIGN KEY (user_id) REFERENCES "users" (id) ON DELETE CASCADE;
ALTER TABLE "orders" ADD CONSTRAINT "orders_user_address_id_foreign" FOREIGN KEY (user_address_id) REFERENCES "shipping_addresses" (id) ON DELETE SET NULL;
ALTER TABLE "orders" ADD CONSTRAINT "orders_user_id_foreign" FOREIGN KEY (user_id) REFERENCES "users" (id) ON DELETE CASCADE;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_order_id_foreign" FOREIGN KEY (order_id) REFERENCES "orders" (id) ON DELETE CASCADE;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_product_id_foreign" FOREIGN KEY (product_id) REFERENCES "products" (id) ON DELETE CASCADE;
ALTER TABLE "payments" ADD CONSTRAINT "payments_order_id_foreign" FOREIGN KEY (order_id) REFERENCES "orders" (id) ON DELETE CASCADE;
ALTER TABLE "products" ADD CONSTRAINT "products_brand_id_foreign" FOREIGN KEY (brand_id) REFERENCES "brands" (id) ON DELETE CASCADE;
ALTER TABLE "products" ADD CONSTRAINT "products_category_id_foreign" FOREIGN KEY (category_id) REFERENCES "categories" (id) ON DELETE CASCADE;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_product_id_foreign" FOREIGN KEY (product_id) REFERENCES "products" (id) ON DELETE CASCADE;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_user_id_foreign" FOREIGN KEY (user_id) REFERENCES "users" (id) ON DELETE CASCADE;
ALTER TABLE "shipping_addresses" ADD CONSTRAINT "shipping_addresses_user_id_foreign" FOREIGN KEY (user_id) REFERENCES "users" (id) ON DELETE CASCADE;
ALTER TABLE "wishlists" ADD CONSTRAINT "wishlists_product_id_foreign" FOREIGN KEY (product_id) REFERENCES "products" (id) ON DELETE CASCADE;
ALTER TABLE "wishlists" ADD CONSTRAINT "wishlists_user_id_foreign" FOREIGN KEY (user_id) REFERENCES "users" (id) ON DELETE CASCADE;

SELECT setval(pg_get_serial_sequence('brands', 'id'), COALESCE((SELECT MAX("id") FROM "brands"), 1), (SELECT COUNT(*) > 0 FROM "brands"));
SELECT setval(pg_get_serial_sequence('cart', 'id'), COALESCE((SELECT MAX("id") FROM "cart"), 1), (SELECT COUNT(*) > 0 FROM "cart"));
SELECT setval(pg_get_serial_sequence('categories', 'id'), COALESCE((SELECT MAX("id") FROM "categories"), 1), (SELECT COUNT(*) > 0 FROM "categories"));
SELECT setval(pg_get_serial_sequence('failed_jobs', 'id'), COALESCE((SELECT MAX("id") FROM "failed_jobs"), 1), (SELECT COUNT(*) > 0 FROM "failed_jobs"));
SELECT setval(pg_get_serial_sequence('migrations', 'id'), COALESCE((SELECT MAX("id") FROM "migrations"), 1), (SELECT COUNT(*) > 0 FROM "migrations"));
SELECT setval(pg_get_serial_sequence('orders', 'id'), COALESCE((SELECT MAX("id") FROM "orders"), 1), (SELECT COUNT(*) > 0 FROM "orders"));
SELECT setval(pg_get_serial_sequence('order_items', 'id'), COALESCE((SELECT MAX("id") FROM "order_items"), 1), (SELECT COUNT(*) > 0 FROM "order_items"));
SELECT setval(pg_get_serial_sequence('payments', 'id'), COALESCE((SELECT MAX("id") FROM "payments"), 1), (SELECT COUNT(*) > 0 FROM "payments"));
SELECT setval(pg_get_serial_sequence('personal_access_tokens', 'id'), COALESCE((SELECT MAX("id") FROM "personal_access_tokens"), 1), (SELECT COUNT(*) > 0 FROM "personal_access_tokens"));
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX("id") FROM "products"), 1), (SELECT COUNT(*) > 0 FROM "products"));
SELECT setval(pg_get_serial_sequence('reviews', 'id'), COALESCE((SELECT MAX("id") FROM "reviews"), 1), (SELECT COUNT(*) > 0 FROM "reviews"));
SELECT setval(pg_get_serial_sequence('shipping_addresses', 'id'), COALESCE((SELECT MAX("id") FROM "shipping_addresses"), 1), (SELECT COUNT(*) > 0 FROM "shipping_addresses"));
SELECT setval(pg_get_serial_sequence('users', 'id'), COALESCE((SELECT MAX("id") FROM "users"), 1), (SELECT COUNT(*) > 0 FROM "users"));
SELECT setval(pg_get_serial_sequence('wishlists', 'id'), COALESCE((SELECT MAX("id") FROM "wishlists"), 1), (SELECT COUNT(*) > 0 FROM "wishlists"));

COMMIT;
